const [qCan, qBasket] = await Promise.all([
  tools.ego_query({ category: "alphabet_soup" }),
  tools.ego_query({ category: "basket" }),
]);
console.log("can:", JSON.stringify(qCan));
console.log("basket:", JSON.stringify(qBasket));

const pred = await tools.ego_predict({ skill: "libero_pick_place", target: "e:1:can", on: "e:1:basket" });
console.log("predict:", JSON.stringify(pred, null, 2));

const run = await tools.skill_run({ receipt: "panda-receipt-c0a1f11d500e402a8c9892466102a633", wait: true, timeoutS: 240 });
console.log("run:", JSON.stringify(run));

let jobId = run?.job ?? run?.jobId ?? run?.id;
console.log("jobId:", jobId);

const deadline = Date.now() + 300000;
let last = run;
let polls = 0;
while (jobId && polls < 60) {
  const terminal = last?.state && last.state !== "running" && last.state !== "queued";
  if (terminal) break;
  if (Date.now() > deadline) break;
  await new Promise((r) => setTimeout(r, 5000));
  last = await tools.skill_status({ job: jobId });
  polls++;
  console.log(`poll ${polls}:`, JSON.stringify(last));
}
console.log("FINAL:", JSON.stringify(last, null, 2));
globalThis.__lastStatus = last;
globalThis.__jobId = jobId;

const code = `
const target = args.target;
const on = args.on;
if (!target || !on) throw new Error("libero_soup_to_basket requires args.target and args.on");

const pred = await tools.ego_predict({ skill: "libero_pick_place", target, on });
if (pred.feasible !== true || pred.withinRiskLimit !== true) {
  throw new Error("libero_pick_place not feasible: " + JSON.stringify({ feasible: pred.feasible, withinRiskLimit: pred.withinRiskLimit, issues: pred.issues, risk: pred.risk }));
}

const run = await tools.skill_run({ receipt: pred.receipt, wait: true, timeoutS: 240 });
const jobId = run.job ?? run.jobId ?? run.id;
if (!jobId) throw new Error("skill_run returned no job: " + JSON.stringify(run));

let last = run;
const deadline = Date.now() + 300000;
let polls = 0;
while (last.state === "running" || last.state === "queued") {
  if (polls >= 60 || Date.now() > deadline) break;
  await new Promise((r) => setTimeout(r, 5000));
  last = await tools.skill_status({ job: jobId });
  polls += 1;
}

const ok = last.state === "succeeded" && last.goalStatus === "achieved" && last.stopStatus === "confirmed";
if (!ok) {
  throw new Error("libero_pick_place did not reach success: " + JSON.stringify({ job: jobId, state: last.state, goalStatus: last.goalStatus, stopStatus: last.stopStatus, message: last.message, reasonCode: last.reasonCode, evidence: last.evidence }));
}
return { job: jobId, state: last.state, goalStatus: last.goalStatus, stopStatus: last.stopStatus, evidence: last.evidence };
`;

const saved = await tools.capability_save({
  name: "libero_soup_to_basket",
  layer: "recipe",
  description: "Place the alphabet soup can into the basket with the body's libero_pick_place skill: predicts a fresh receipt, runs it, polls the same job to a terminal state, and returns only when state=succeeded, goalStatus=achieved and stopStatus=confirmed.",
  requires: "A LIBERO Panda body whose skills include libero_pick_place; the soup can and basket are perceived in ego_state and their ids are passed as args.target and args.on.",
  ensures: "The can rests in the basket (grasp and placement confirmed by the skill's evidence) and the returned object reports state=succeeded, goalStatus=achieved, stopStatus=confirmed; otherwise throws an Error carrying the job status instead of retrying.",
  parameters: {
    target: "ES reference of the alphabet soup can to pick (for example e:1:can)",
    on: "ES reference of the basket to place it in (for example e:1:basket)",
  },
  code,
});
console.log("saved:", JSON.stringify(saved, null, 2));

